'use client';
import {useEffect,useState} from 'react';import {useParams,useRouter}from 'next/navigation';export default function Interview(){const{interviewId}=useParams();const router=useRouter();const[report,setReport]=useState(null);const[loading,setLoading]=useState(true);useEffect(()=>{if(!interviewId)return;fetch(`/api/interview/report/${interviewId}`).then(async r=>{if(r.status===401){router.replace('/login');return null}return r.json()}).then(d=>setReport(d?.interviewReport||null)).finally(()=>setLoading(false));},[interviewId,router]);async function downloadPdf(){const r=await fetch(`/api/interview/resume/pdf/${interviewId}`,{method:'POST'});if(!r.ok)return;const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`resume_${interviewId}.pdf`;a.click();URL.revokeObjectURL(url)}if(loading)return <main className="loading-screen"><h1>Loading report...</h1></main>;if(!report)return <main><h1>Report not found</h1></main>;return <main className="interview-page"><header><h1>{report.title||'Interview Report'}</h1><p>Match score: {report.matchScore}%</p><button className="button primary-button" onClick={downloadPdf}>Generate Tailored Resume PDF</button></header><section><h2>Technical Questions</h2>{report.technicalQuestions?.map((q,i)=><article className="q-card" key={i}><h3>{q.question}</h3><p><strong>Intention:</strong> {q.intention}</p><p><strong>Answer:</strong> {q.answer}</p></article>)}</section><section><h2>Behavioral Questions</h2>{report.behavioralQuestions?.map((q,i)=><article className="q-card" key={i}><h3>{q.question}</h3><p>{q.answer}</p></article>)}</section><section><h2>Preparation Plan</h2>{report.preparationPlan?.map(d=><article key={d.day}><h3>Day {d.day}: {d.focus}</h3><ul>{d.tasks?.map((t,i)=><li key={i}>{t}</li>)}</ul></article>)}</section></main>}
